import type { Metadata } from "next";
import type { Faq } from "./content/types";
import { absoluteUrl, siteConfig } from "./site";

/** The social share card (generated by scripts/generate-brand-assets.mjs). */
export const OG_IMAGE = {
  url: "/opengraph-image.png",
  width: 1200,
  height: 630,
  alt: "Reseny Connect: every lead called, every appointment booked.",
};

interface PageMetadataInput {
  title: string;
  description: string;
  /** Site-relative path, e.g. "/pricing". Used for the canonical URL. */
  path: string;
  /** Keep out of search results (thank-you pages, campaign landing pages). */
  noindex?: boolean;
}

/** Per-page metadata with a canonical URL and matching Open Graph / Twitter tags. */
export function pageMetadata({ title, description, path, noindex = false }: PageMetadataInput): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      title,
      description,
      url: path,
      siteName: siteConfig.name,
      type: "website",
      locale: "en_IN",
      images: [OG_IMAGE],
    },
    twitter: { card: "summary_large_image", title, description, images: [OG_IMAGE.url] },
    ...(noindex ? { robots: { index: false, follow: false } } : {}),
  };
}

export function organizationJsonLd() {
  return {
    "@context": "https://schema.org",
    "@type": "Organization",
    name: siteConfig.company,
    alternateName: [siteConfig.brand, siteConfig.name],
    url: siteConfig.url,
    logo: absoluteUrl("/brand/reseny-logo.webp"),
    description: siteConfig.description,
    parentOrganization: {
      "@type": "Organization",
      name: siteConfig.parentCompany,
      foundingDate: String(siteConfig.parentSince),
    },
    ...(siteConfig.social.length ? { sameAs: siteConfig.social.map((item) => item.href) } : {}),
    ...(siteConfig.contact.salesEmail || siteConfig.contact.phone
      ? {
          contactPoint: {
            "@type": "ContactPoint",
            contactType: "sales",
            ...(siteConfig.contact.salesEmail ? { email: siteConfig.contact.salesEmail } : {}),
            ...(siteConfig.contact.phone ? { telephone: siteConfig.contact.phone } : {}),
          },
        }
      : {}),
  };
}

export function websiteJsonLd() {
  return {
    "@context": "https://schema.org",
    "@type": "WebSite",
    name: siteConfig.name,
    url: siteConfig.url,
    description: siteConfig.description,
  };
}

export function softwareJsonLd() {
  return {
    "@context": "https://schema.org",
    "@type": "SoftwareApplication",
    name: siteConfig.name,
    applicationCategory: "BusinessApplication",
    operatingSystem: "Web",
    description: siteConfig.description,
    url: siteConfig.url,
    publisher: { "@type": "Organization", name: siteConfig.company },
  };
}

export function breadcrumbJsonLd(items: { name: string; path: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: items.map((item, index) => ({
      "@type": "ListItem",
      position: index + 1,
      name: item.name,
      item: absoluteUrl(item.path),
    })),
  };
}

export function faqJsonLd(faqs: readonly Faq[]) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: faqs.map((faq) => ({
      "@type": "Question",
      name: faq.question,
      acceptedAnswer: { "@type": "Answer", text: faq.answer },
    })),
  };
}
